"""In-memory TTL report store (approved Rev. 3, M7; decisions D4 and D6).

* Holds derived ``AnalysisReport`` objects only, in process memory. Nothing is
  written to disk and reports are lost on restart (one worker by design).
* Keys are UUID4 values generated by the store itself; callers never choose
  them. Lookups accept only the canonical hyphenated UUID4 form, so unknown,
  malformed and expired IDs are indistinguishable to callers (all ``None``).
* A report expires ``ttl_seconds`` after creation. Expired reports are purged
  on access and by a periodic sweep.
* At most ``max_reports`` reports are held. When the store is full, expired
  reports are purged first; if it is still full, ``ReportStoreFullError``
  (503) is raised and nothing is stored.
* There is deliberately no way to list, iterate or enumerate reports.
* All operations run on the event loop under one ``asyncio.Lock``. Stored and
  returned reports are deep copies, so no caller can mutate a stored report.
* Report IDs and content are never logged.
"""

from __future__ import annotations

import asyncio
import contextlib
import logging
import re
import uuid
from collections.abc import Callable
from dataclasses import dataclass
from datetime import UTC, datetime, timedelta

from backend.core.errors import AppError
from backend.schemas.report import AnalysisReport

logger = logging.getLogger("backend.storage.report_store")

Clock = Callable[[], datetime]

_UUID4 = re.compile(
    r"^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$", re.IGNORECASE
)


class ReportStoreFullError(AppError):
    status_code = 503
    code = "report_store_full"
    message = "The service is at capacity. Please try again later."


def parse_report_id(value: str) -> uuid.UUID | None:
    """The UUID for a canonical UUID4 string, or ``None`` for anything else."""
    if not isinstance(value, str) or not _UUID4.fullmatch(value):
        return None
    return uuid.UUID(value)


def _utc_now() -> datetime:
    return datetime.now(UTC)


@dataclass(frozen=True)
class ReportStamp:
    """Identity and lifetime the store assigns to a new report."""

    report_id: uuid.UUID
    created_at: datetime
    expires_at: datetime


class ReportStore:
    def __init__(
        self,
        *,
        ttl_seconds: int,
        max_reports: int,
        sweep_interval_seconds: float,
        clock: Clock = _utc_now,
    ) -> None:
        if ttl_seconds <= 0 or max_reports <= 0 or sweep_interval_seconds <= 0:
            raise ValueError("ttl, capacity and sweep interval must be positive")
        self._ttl = timedelta(seconds=ttl_seconds)
        self._max_reports = max_reports
        self._sweep_interval = sweep_interval_seconds
        self._clock = clock
        self._reports: dict[uuid.UUID, AnalysisReport] = {}
        self._lock = asyncio.Lock()
        self._sweeper: asyncio.Task[None] | None = None

    # --- reports -----------------------------------------------------------------------

    async def create(self, build: Callable[[ReportStamp], AnalysisReport]) -> AnalysisReport:
        """Assign an ID and lifetime, build the report with them and store it.

        ``build`` runs under the store lock and must be synchronous and quick.
        Returns a copy of the stored report.
        """
        async with self._lock:
            now = self._now()
            if len(self._reports) >= self._max_reports:
                self._purge_expired(now)
            if len(self._reports) >= self._max_reports:
                logger.warning("report_store_full", extra={"component": "report_store"})
                raise ReportStoreFullError()
            report_id = uuid.uuid4()
            while report_id in self._reports:  # pragma: no cover - 122 random bits
                report_id = uuid.uuid4()
            stamp = ReportStamp(report_id, now, now + self._ttl)
            report = build(stamp)
            # Exact type: a subclass could add fields (for example raw text).
            if type(report) is not AnalysisReport:
                raise TypeError("the report store holds AnalysisReport objects only")
            if (report.report_id, report.created_at, report.expires_at) != (
                stamp.report_id,
                stamp.created_at,
                stamp.expires_at,
            ):
                raise ValueError("report identity and lifetime must come from the stamp")
            self._reports[report_id] = report.model_copy(deep=True)
            return report.model_copy(deep=True)

    async def get(self, report_id: str) -> AnalysisReport | None:
        """A copy of the report, or ``None`` if the ID is malformed, unknown or expired."""
        key = parse_report_id(report_id)
        if key is None:
            return None
        async with self._lock:
            report = self._reports.get(key)
            if report is None:
                return None
            if self._is_expired(report, self._now()):
                del self._reports[key]
                return None
            return report.model_copy(deep=True)

    async def purge_expired(self) -> int:
        """Remove every expired report; returns how many were removed."""
        async with self._lock:
            return self._purge_expired(self._now())

    async def count(self) -> int:
        """Number of reports currently held (expired ones included until purged)."""
        async with self._lock:
            return len(self._reports)

    # --- periodic sweep ----------------------------------------------------------------

    @property
    def running(self) -> bool:
        return self._sweeper is not None and not self._sweeper.done()

    async def start(self) -> None:
        if self._sweeper is None:
            self._sweeper = asyncio.create_task(self._sweep_forever(), name="report-store-sweep")

    async def stop(self) -> None:
        if self._sweeper is not None:
            self._sweeper.cancel()
            with contextlib.suppress(asyncio.CancelledError):
                await self._sweeper
            self._sweeper = None
        async with self._lock:
            self._reports.clear()

    async def _sweep_forever(self) -> None:
        while True:
            await asyncio.sleep(self._sweep_interval)
            try:
                await self.purge_expired()
            except Exception as exc:  # noqa: BLE001 - the sweep must keep running
                logger.error(
                    "report_store_sweep_failed",
                    extra={"component": "report_store", "error_code": type(exc).__name__},
                )

    # --- internals (call with the lock held) -------------------------------------------

    def _now(self) -> datetime:
        now = self._clock()
        if now.tzinfo is None:
            raise ValueError("the report store clock must return timezone-aware datetimes")
        return now

    @staticmethod
    def _is_expired(report: AnalysisReport, now: datetime) -> bool:
        return now >= report.expires_at

    def _purge_expired(self, now: datetime) -> int:
        expired = [key for key, report in self._reports.items() if self._is_expired(report, now)]
        for key in expired:
            del self._reports[key]
        return len(expired)
